     2→import { IPC } from "../shared/ipc-channels";
     3→import type { Agent } from "../shared/types/agent";
     4→import type { Skill } from "../shared/types/skill";
     5→import type { InstalledPlugin } from "../shared/types/plugin";
     6→import type { Command } from "../shared/types/command";
     7→import type { Settings } from "../shared/types/settings";
     8→import type {
     9→  MarketplaceSource,
    10→  MarketplacePlugin,
    11→  MarketplacePluginDetail,
    12→  InstalledPluginRecord,
    13→} from "../shared/types/marketplace";
    14→import type { HookDefinition } from "../shared/types/hook";
    15→import type { MCPServer } from "../shared/types/mcp";
    16→
    17→// Types for plugin detail
    18→interface PluginDetail {
    19→  manifest: { name: string; version: string; description: string } | null;
    20→  agents: Agent[];
    21→  skills: Skill[];
    22→  commands: Command[];
    23→  hooks: Array<{
    24→    pluginId: string;
    25→    event: string;
    26→    matcher: string;
    27→    hooks: unknown[];
    28→  }>;
    29→}
    30→
    31→// File tree node type
    32→interface FileNode {
    33→  name: string;
    34→  path: string;
    35→  isDirectory: boolean;
    36→  children?: FileNode[];
    37→}
    38→
    39→const api = {
    40→  agents: {
    41→    list: (): Promise<Agent[]> => ipcRenderer.invoke(IPC.AGENTS_LIST),
    42→    read: (name: string): Promise<Agent | null> =>
    43→      ipcRenderer.invoke(IPC.AGENTS_READ, name),
    44→    write: (
    45→      name: string,
    46→      data: {
    47→        name: string;
    48→        description: string;
    49→        tools: string[];
    50→        model: string;
    51→        body: string;
    52→      },
    53→    ): Promise<void> => ipcRenderer.invoke(IPC.AGENTS_WRITE, name, data),
    54→    delete: (name: string): Promise<void> =>
    55→      ipcRenderer.invoke(IPC.AGENTS_DELETE, name),
    56→  },
