    24→    // 2. Plugin agents
    25→    const pluginAgents = await this.getPluginAgents()
    26→    agents.push(...pluginAgents)
    27→
    28→    return agents
    29→  }
    30→
    31→  async read(name: string): Promise<Agent | null> {
    32→    const filePath = join(AGENTS_DIR, `${name}.md`)
    33→    if (!(await fsService.exists(filePath))) return null
    34→    try {
    35→      const content = await fsService.readFile(filePath)
    36→      return parserService.parseAgent(content, filePath, 'personal')
    37→    } catch {
    38→      return null
    39→    }
    40→  }
    41→
    42→  async write(name: string, data: { name: string; description: string; tools: string[]; model: string; body: string }): Promise<void> {
    43→    const filePath = join(AGENTS_DIR, `${name}.md`)
    44→    const content = parserService.serializeAgent(data)
    45→    await fsService.writeFileAtomic(filePath, content)
    46→  }
    47→
    48→  async delete(name: string): Promise<void> {
    49→    const filePath = join(AGENTS_DIR, `${name}.md`)
