    54→    const agents: Agent[] = []
    55→    try {
    56→      if (!(await fsService.exists(INSTALLED_PLUGINS_FILE))) return agents
    57→      const data = await pluginService.getPluginsObject()
    58→
    59→      // Check which plugins are enabled
    60→      let enabledPlugins: Record<string, boolean> = {}
    61→      if (await fsService.exists(SETTINGS_FILE)) {
    62→        const settings = await fsService.readJSON<{ enabledPlugins?: Record<string, boolean> }>(SETTINGS_FILE)
    63→        enabledPlugins = settings.enabledPlugins || {}
    64→      }
    65→
    66→      for (const [pluginId, info] of Object.entries(data)) {
    67→        if (!enabledPlugins[pluginId]) continue
    68→        const agentsDir = join(info.installPath, 'agents')
    69→        if (!(await fsService.exists(agentsDir))) continue
    70→        const files = await fsService.listFiles(agentsDir, '.md')
    71→        for (const file of files) {
    72→          try {
    73→            const filePath = join(agentsDir, file)
    74→            const content = await fsService.readFile(filePath)
    75→            agents.push(parserService.parseAgent(content, filePath, 'plugin', pluginId))
    76→          } catch {
    77→            // skip
    78→          }
    79→        }
    80→      }
    81→    } catch {
    82→      // skip
    83→    }
    84→    return agents
    85→  }
    86→}
