import { HashRouter, Routes, Route } from "react-router-dom";
import { AppShell } from "./components/layout/AppShell";
import { SearchCommand } from "./components/shared/SearchCommand";
import { ToastProvider } from "./components/shared/Toast";
import { LanguageProvider } from "./i18n/LanguageContext";
import { useTheme } from "./hooks/useTheme";
import { DashboardPage } from "./pages/DashboardPage";
import { AgentsPage } from "./pages/AgentsPage";
import { AgentDetailPage } from "./pages/AgentDetailPage";
import { SkillsPage } from "./pages/SkillsPage";
import { SkillDetailPage } from "./pages/SkillDetailPage";
import { SkillNewPage } from "./pages/SkillNewPage";
import { SkillsTreePage } from "./pages/SkillsTreePage";
import { PluginsPage } from "./pages/PluginsPage";
import { PluginDetailPage } from "./pages/PluginDetailPage";
import { CommandsPage } from "./pages/CommandsPage";
import { CommandDetailPage } from "./pages/CommandDetailPage";
import { HooksPage } from "./pages/HooksPage";
import { MCPPage } from "./pages/MCPPage";
import { MarketplacePage } from "./pages/MarketplacePage";
import { SettingsPage } from "./pages/SettingsPage";
import { ProjectsListPage } from "./pages/ProjectsListPage";
import { ProjectDetailPage } from "./pages/ProjectDetailPage";
import { PlansPage } from "./pages/PlansPage";

function ThemedApp(): JSX.Element {
  // Initialize theme
  useTheme();

  return (
    <ToastProvider>
      <HashRouter>
        <SearchCommand />
        <Routes>
          <Route element={<AppShell />}>
            <Route path="/" element={<DashboardPage />} />
            <Route path="/agents" element={<AgentsPage />} />
            <Route path="/agents/:name" element={<AgentDetailPage />} />
            <Route path="/skills" element={<SkillsPage />} />
            <Route path="/skills/new" element={<SkillNewPage />} />
            <Route path="/skills/tree" element={<SkillsTreePage />} />
            <Route path="/skills/:source/:name" element={<SkillDetailPage />} />
            <Route path="/plugins" element={<PluginsPage />} />
            <Route path="/plugins/:id" element={<PluginDetailPage />} />
            <Route path="/commands" element={<CommandsPage />} />
            <Route
              path="/commands/:pluginId/:name"
              element={<CommandDetailPage />}
            />
            <Route path="/hooks" element={<HooksPage />} />
            <Route path="/mcp" element={<MCPPage />} />
            <Route path="/marketplace" element={<MarketplacePage />} />
            <Route path="/settings" element={<SettingsPage />} />
            <Route path="/office" element={<ProjectsListPage />} />
            <Route path="/office/project/:projectDir" element={<ProjectDetailPage />} />
            <Route path="/plans" element={<PlansPage />} />
          </Route>
        </Routes>
      </HashRouter>
    </ToastProvider>
  );
}

export function App(): JSX.Element {
  return (
    <LanguageProvider>
      <ThemedApp />
    </LanguageProvider>
  );
}

import { create } from 'zustand'
import type { Agent } from '@shared/types/agent'

interface AgentStore {
  items: Agent[]
  loading: boolean
  fetch: () => Promise<void>
  deleteAgent: (name: string) => Promise<void>
}

export const useAgentStore = create<AgentStore>((set) => ({
  items: [],
  loading: false,
  async fetch() {
    if (!window.electronAPI) return
    set({ loading: true })
    try {
      const agents = await window.electronAPI.agents.list()
      set({ items: agents })
    } finally {
      set({ loading: false })
    }
  },
  async deleteAgent(name: string) {
    await window.electronAPI.agents.delete(name)
    set(state => ({ items: state.items.filter(a => a.name !== name) }))
  }
}))

