     1→import { useState } from "react";
     2→import { Terminal, Trash2, CheckSquare, Square } from "lucide-react";
     3→import { useTranslation } from "../../i18n/LanguageContext";
     4→
     5→export interface AgentInfo {
     6→  id: number;
     7→  sessionId: string;
     8→  projectDir: string;
     9→  isActive: boolean;
    10→  lastModified?: string;
    11→}
    12→
    13→interface AgentListProps {
    14→  agents: AgentInfo[];
    15→  selectedAgentId?: number;
    16→  onSelectAgent: (agent: AgentInfo) => void;
    17→  onJoinTerminal: (projectDir: string, sessionId?: string) => void;
    18→  onDeleteAgent: (projectDir: string, sessionId: string) => void;
    19→  onBatchDelete?: (projectDir: string, sessionIds: string[]) => void;
    20→  title?: string;
    21→}
    22→
    23→export function AgentList({
    24→  agents,
    25→  selectedAgentId,
    26→  onSelectAgent,
    27→  onJoinTerminal,
    28→  onDeleteAgent,
    29→  onBatchDelete,
    30→  title,
    31→}: AgentListProps): JSX.Element {
    32→  const { t } = useTranslation();
    33→  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
    34→  const [isBatchMode, setIsBatchMode] = useState(false);
    35→
    36→  if (agents.length === 0) {
    37→    return (
    38→      <div className="text-center text-muted-foreground py-8">
    39→        {t("office.noSessionsInProject")}
    40→      </div>
    41→    );
    42→  }
    43→
    44→  // 按活跃状态排序，活跃的排在前面
    45→  const sortedAgents = [...agents].sort((a, b) => {
    46→    if (a.isActive && !b.isActive) return -1;
    47→    if (!a.isActive && b.isActive) return 1;
    48→    return 0;
    49→  });
    50→
    51→  const handleToggleSelect = (sessionId: string): void => {
    52→    setSelectedIds((prev) => {
    53→      const next = new Set(prev);
    54→      if (next.has(sessionId)) {
    55→        next.delete(sessionId);
    56→      } else {
    57→        next.add(sessionId);
    58→      }
    59→      return next;
    60→    });
    61→  };
    62→
    63→  const handleSelectAll = (): void => {
    64→    if (selectedIds.size === sortedAgents.length) {
    65→      setSelectedIds(new Set());
    66→    } else {
    67→      setSelectedIds(new Set(sortedAgents.map((a) => a.sessionId)));
    68→    }
    69→  };
    70→
    71→  const handleBatchDelete = (): void => {
    72→    if (!onBatchDelete || selectedIds.size === 0) return;
    73→    const projectDir = sortedAgents[0]?.projectDir;
    74→    if (!projectDir) return;
    75→
    76→    if (confirm(t("office.batchDeleteConfirm", { count: selectedIds.size }))) {
    77→      onBatchDelete(projectDir, Array.from(selectedIds));
    78→      setSelectedIds(new Set());
    79→      setIsBatchMode(false);
    80→    }
    81→  };
    82→
    83→  const getCardClassName = (agent: AgentInfo): string => {
    84→    const isSelected = selectedAgentId === agent.id;
    85→    const isChecked = selectedIds.has(agent.sessionId);
    86→
    87→    // 选中状态优先显示
    88→    if (isSelected && isBatchMode) {
    89→      return "bg-primary/20 border-2 border-primary";
    90→    }
    91→    if (isSelected) {
    92→      return "bg-primary/20 border-2 border-primary";
    93→    }
    94→    if (agent.isActive) {
    95→      return "bg-green-500/5 border border-green-500/30 hover:border-green-500/50";
    96→    }
    97→    return "bg-card border border-border hover:border-primary/30";
    98→  };
    99→
   100→  return (
   101→    <div className="space-y-3">
   102→      {/* 标题和Batch操作工具栏 */}
   103→      <div className="flex items-center justify-between pb-2 border-b border-border">
   104→        <div className="flex items-center gap-2">
   105→          {title && <h2 className="font-semibold">{title}</h2>}
   106→          {onBatchDelete && (
   107→            <button
   108→              className={`flex items-center gap-1 text-sm px-2 py-1 rounded ${
   109→                isBatchMode ? "text-primary bg-primary/10" : "text-muted-foreground hover:text-foreground"
   110→              }`}
   111→              onClick={() => {
   112→                setIsBatchMode(!isBatchMode);
   113→                if (!isBatchMode) setSelectedIds(new Set());
   114→              }}
