import {
  readFile,
  writeFile,
  readdir,
  stat,
  mkdir,
  unlink,
  rename,
  copyFile,
  readlink,
  symlink,
  realpath,
} from "fs/promises";
import { existsSync } from "fs";
import { join, dirname, resolve } from "path";
import { tmpdir } from "os";
import { randomUUID } from "crypto";

export interface FileNode {
  name: string;
  path: string;
  isDirectory: boolean;
  children?: FileNode[];
}

export class FileSystemService {
  async readFile(path: string): Promise<string> {
    return readFile(path, "utf-8");
  }

  async writeFileAtomic(path: string, content: string): Promise<void> {
    await mkdir(dirname(path), { recursive: true });
    const tmp = join(tmpdir(), `csam-${randomUUID()}.tmp`);
    await writeFile(tmp, content, "utf-8");
    await rename(tmp, path);
  }

  async readJSON<T>(path: string): Promise<T> {
    const content = await this.readFile(path);
    return JSON.parse(content);
  }

  async writeJSON(path: string, data: unknown): Promise<void> {
    await this.writeFileAtomic(path, JSON.stringify(data, null, 2) + "\n");
  }

  async listFiles(dir: string, ext?: string): Promise<string[]> {
    if (!existsSync(dir)) return [];
    const entries = await readdir(dir, { withFileTypes: true });
    let files = entries.filter((e) => e.isFile()).map((e) => e.name);
    if (ext) files = files.filter((f) => f.endsWith(ext));
    return files;
  }

  async listDirs(dir: string): Promise<string[]> {
    if (!existsSync(dir)) return [];
    const entries = await readdir(dir, { withFileTypes: true });
    return entries.filter((e) => e.isDirectory()).map((e) => e.name);
  }

  async exists(path: string): Promise<boolean> {
    return existsSync(path);
  }

  async deleteFile(path: string): Promise<void> {
    await unlink(path);
  }

  async ensureDir(path: string): Promise<void> {
    await mkdir(path, { recursive: true });
  }

  async getFileMtime(path: string): Promise<Date> {
    const s = await stat(path);
    return s.mtime;
  }

  async copyDirectory(
    src: string,
    dest: string,
    copiedPaths = new Set<string>(),
  ): Promise<void> {
    const resolvedDest = resolve(dest);
    const realSrc = await realpath(src).catch(() => resolve(src));

    if (copiedPaths.has(realSrc)) {
      return;
    }
    copiedPaths.add(realSrc);

    await mkdir(dest, { recursive: true });
    const entries = await readdir(src, { withFileTypes: true });

    for (const entry of entries) {
      const srcPath = join(src, entry.name);
      const destPath = join(dest, entry.name);

      // Skip if this entry IS the destination (prevents self-copy loop)
      const resolvedSrcPath = resolve(srcPath);
      if (
        resolvedSrcPath === resolvedDest ||
        resolvedDest.startsWith(resolvedSrcPath + "/")
      ) {
        continue;
      }

      if (entry.isSymbolicLink()) {
        const linkTarget = await readlink(srcPath);
        await symlink(linkTarget, destPath);
      } else if (entry.isDirectory()) {
        await this.copyDirectory(srcPath, destPath, copiedPaths);
      } else {
        await copyFile(srcPath, destPath);
      }
    }
  }

  async readDirectoryTree(
    dir: string,
    maxDepth: number = 3,
  ): Promise<FileNode[]> {
    if (!existsSync(dir)) return [];

    const entries = await readdir(dir, { withFileTypes: true });
    const nodes: FileNode[] = [];

    for (const entry of entries) {
      if (entry.name.startsWith(".")) continue; // Skip hidden files

      const fullPath = join(dir, entry.name);

      if (entry.isDirectory()) {
        const node: FileNode = {
          name: entry.name,
          path: fullPath,
          isDirectory: true,
          children: [],
        };

        if (maxDepth > 1) {
          node.children = await this.readDirectoryTree(fullPath, maxDepth - 1);
        }

        nodes.push(node);
      } else {
        nodes.push({
          name: entry.name,
          path: fullPath,
          isDirectory: false,
        });
      }
    }

    // Sort: directories first, then files, alphabetically
    return nodes.sort((a, b) => {
      if (a.isDirectory && !b.isDirectory) return -1;
      if (!a.isDirectory && b.isDirectory) return 1;
      return a.name.localeCompare(b.name);
    });
  }
}

export const fsService = new FileSystemService();

import { NavLink } from "react-router-dom";
import {
  LayoutDashboard,
  Bot,
  Sparkles,
  Puzzle,
  Terminal,
  Webhook,
  Server,
  Store,
  Settings,
  Layout,
  FileStack,
  type LucideIcon,
} from "lucide-react";
import { ThemeToggle } from "../shared/ThemeToggle";
import { useTranslation } from "../../i18n/LanguageContext";
import logoUrl from "../../assets/logo.svg?url";

interface NavItem {
  path: string;
  label: string;
  icon: LucideIcon;
}

export function Sidebar(): JSX.Element {
  const { t } = useTranslation();

  const navItems: NavItem[] = [
    { path: "/", label: t("sidebar.nav.dashboard"), icon: LayoutDashboard },
    { path: "/agents", label: t("sidebar.nav.agents"), icon: Bot },
    { path: "/skills", label: t("sidebar.nav.skills"), icon: Sparkles },
    { path: "/plugins", label: t("sidebar.nav.plugins"), icon: Puzzle },
    { path: "/commands", label: t("sidebar.nav.commands"), icon: Terminal },
    { path: "/hooks", label: t("sidebar.nav.hooks"), icon: Webhook },
    { path: "/mcp", label: t("sidebar.nav.mcp"), icon: Server },
    { path: "/marketplace", label: t("sidebar.nav.marketplace"), icon: Store },
    { path: "/office", label: t("sidebar.nav.office"), icon: Layout },
    { path: "/plans", label: t("sidebar.nav.plans"), icon: FileStack },
    { path: "/settings", label: t("sidebar.nav.settings"), icon: Settings },
  ];

  return (
    <aside className="fixed left-0 top-0 bottom-0 w-64 bg-zinc-100 dark:bg-zinc-900 border-r border-zinc-200 dark:border-zinc-800 flex flex-col">
      {/* Title / drag region */}
      <div className="drag-region h-20 flex items-center gap-3 px-5 pt-8">
        <img src={logoUrl} alt="Logo" className="no-drag w-10 h-10 shrink-0" />
        <h1
          className="no-drag text-xl font-bold tracking-tight text-zinc-700 dark:text-zinc-300"
          style={{
            fontFamily:
              "SF Pro Display, -apple-system, BlinkMacSystemFont, sans-serif",
          }}
        >
          {t("sidebar.title")}
        </h1>
      </div>

      {/* Navigation */}
      <nav className="flex-1 overflow-y-auto px-3 py-2">
        <ul className="space-y-0.5">
          {navItems.map((item) => (
            <li key={item.path}>
              <NavLink
                to={item.path}
                end={item.path === "/"}
                className={({ isActive }) =>
                  `flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-colors ${
                    isActive
                      ? "bg-zinc-200 dark:bg-zinc-800 text-zinc-900 dark:text-zinc-100 font-medium"
                      : "text-zinc-600 dark:text-zinc-400 hover:bg-zinc-200/60 dark:hover:bg-zinc-800/60"
                  }`
                }
              >
                <item.icon className="w-4 h-4 shrink-0" />
                <span>{item.label}</span>
              </NavLink>
            </li>
          ))}
        </ul>
      </nav>

      {/* Footer */}
      <div className="flex items-center justify-between px-5 py-3 border-t border-zinc-200 dark:border-zinc-800">
        <p className="text-xs text-zinc-400 dark:text-zinc-600">v1.0.0</p>
        <ThemeToggle />
      </div>
    </aside>
  );
}

