### Phase 2: Backend Service Layer

#### 2A. Create `ProjectConfigService` (new service)

**New file:** `/Users/yangsmac/Desktop/claude-skills-and-agents-manager/src/main/services/ProjectConfigService.ts`

This is the central service for all project-scoped config operations. It delegates to `ParserService` and `FileSystemService` (reusing existing infrastructure).

```typescript
import { join } from 'path'
import { fsService } from './FileSystemService'
import { parserService } from './ParserService'
import type { Agent } from '../../shared/types/agent'
import type { Skill } from '../../shared/types/skill'
import type { MCPServer } from '../../shared/types/mcp'
import type { ProjectDetailInfo } from '../../shared/types/project'

export class ProjectConfigService {
  // --- Agents ---

  private getProjectAgentsDir(projectDir: string): string {
    return join(projectDir, '.claude', 'agents')
  }

  async listProjectAgents(projectDir: string): Promise<Agent[]> {
    const agentsDir = this.getProjectAgentsDir(projectDir)
    const agents: Agent[] = []
    const files = await fsService.listFiles(agentsDir, '.md')
    for (const file of files) {
      try {
        const filePath = join(agentsDir, file)
        const content = await fsService.readFile(filePath)
        const agent = parserService.parseAgent(content, filePath, 'personal') // parse same way
        agents.push({ ...agent, source: 'project', projectDir })
      } catch { /* skip */ }
    }
    return agents
  }

  async readProjectAgent(projectDir: string, name: string): Promise<Agent | null> {
    const filePath = join(this.getProjectAgentsDir(projectDir), `${name}.md`)
    if (!(await fsService.exists(filePath))) return null
    const content = await fsService.readFile(filePath)
    const agent = parserService.parseAgent(content, filePath, 'personal')
    return { ...agent, source: 'project', projectDir }
  }

  async writeProjectAgent(projectDir: string, name: string, data: {
    name: string; description: string; tools: string[]; model: string; body: string
  }): Promise<void> {
    const agentsDir = this.getProjectAgentsDir(projectDir)
    await fsService.ensureDir(agentsDir)
    const filePath = join(agentsDir, `${name}.md`)
    const content = parserService.serializeAgent(data)
    await fsService.writeFileAtomic(filePath, content)
  }

  async deleteProjectAgent(projectDir: string, name: string): Promise<void> {
    const filePath = join(this.getProjectAgentsDir(projectDir), `${name}.md`)
    await fsService.deleteFile(filePath)
  }

  // --- Skills ---

  private getProjectSkillsDir(projectDir: string): string {
    return join(projectDir, '.claude', 'skills')
  }

  async listProjectSkills(projectDir: string): Promise<Skill[]> {
    const skillsDir = this.getProjectSkillsDir(projectDir)
    const skills: Skill[] = []
    const dirs = await fsService.listDirs(skillsDir)
    for (const dir of dirs) {
      if (dir === 'learned') continue
      const skillFile = join(skillsDir, dir, 'SKILL.md')
      if (!(await fsService.exists(skillFile))) continue
      try {
        const content = await fsService.readFile(skillFile)
        const hasRef = await fsService.exists(join(skillsDir, dir, 'reference'))
        const hasTpl = await fsService.exists(join(skillsDir, dir, 'templates'))
        const skill = parserService.parseSkill(content, skillFile, 'personal', undefined, hasRef, hasTpl)
        skills.push({ ...skill, source: 'project', projectDir })
      } catch { /* skip */ }
    }
    return skills
  }

  async readProjectSkill(projectDir: string, name: string): Promise<Skill | null> {
    const skillFile = join(this.getProjectSkillsDir(projectDir), name, 'SKILL.md')
    if (!(await fsService.exists(skillFile))) return null
    const content = await fsService.readFile(skillFile)
    const hasRef = await fsService.exists(join(this.getProjectSkillsDir(projectDir), name, 'reference'))
    const hasTpl = await fsService.exists(join(this.getProjectSkillsDir(projectDir), name, 'templates'))
    const skill = parserService.parseSkill(content, skillFile, 'personal', undefined, hasRef, hasTpl)
    return { ...skill, source: 'project', projectDir }
  }

  async writeProjectSkill(projectDir: string, name: string, body: string, metadata: Record<string, unknown>): Promise<void> {
    const dir = join(this.getProjectSkillsDir(projectDir), name)
    await fsService.ensureDir(dir)
    const content = parserService.serializeFrontmatter(metadata, body)
    await fsService.writeFileAtomic(join(dir, 'SKILL.md'), content)
  }

  async deleteProjectSkill(projectDir: string, name: string): Promise<void> {
    const { rm } = await import('fs/promises')
    const dir = join(this.getProjectSkillsDir(projectDir), name)
    await rm(dir, { recursive: true, force: true })
  }

  // --- MCP Servers ---

  private getProjectMcpFile(projectDir: string): string {
    return join(projectDir, '.mcp.json')
  }

  async listProjectMcpServers(projectDir: string): Promise<MCPServer[]> {
    const mcpFile = this.getProjectMcpFile(projectDir)
    if (!(await fsService.exists(mcpFile))) return []
    try {
      const config = await fsService.readJSON<{ mcpServers?: Record<string, Partial<MCPServer>> }>(mcpFile)
      const servers = config.mcpServers || {}
      return Object.entries(servers).map(([name, server]) => ({
        name,
        type: (server.type || 'stdio') as MCPServer['type'],
        command: server.command,
        args: server.args,
        url: server.url,
        env: server.env,
        active: true,
      }))
    } catch { return [] }
  }

  async addProjectMcpServer(projectDir: string, name: string, config: Partial<MCPServer>): Promise<void> {
    const mcpFile = this.getProjectMcpFile(projectDir)
    let existing: { mcpServers?: Record<string, unknown> } = {}
    if (await fsService.exists(mcpFile)) {
      try { existing = await fsService.readJSON(mcpFile) } catch { /* use empty */ }
    }
    if (!existing.mcpServers) existing.mcpServers = {}
    existing.mcpServers[name] = {
      type: config.type || 'stdio',
      ...(config.command && { command: config.command }),
      ...(config.args && { args: config.args }),
      ...(config.url && { url: config.url }),
      ...(config.env && { env: config.env }),
    }
    await fsService.writeJSON(mcpFile, existing)
  }

  async updateProjectMcpServer(projectDir: string, name: string, updates: Partial<MCPServer>): Promise<void> {
    // Same pattern as addProjectMcpServer but merges with existing entry
    const mcpFile = this.getProjectMcpFile(projectDir)
    const config = await fsService.readJSON<{ mcpServers?: Record<string, unknown> }>(mcpFile)
    if (!config.mcpServers?.[name]) throw new Error(`Server "${name}" not found`)
    config.mcpServers[name] = { ...(config.mcpServers[name] as object), ...updates }
    await fsService.writeJSON(mcpFile, config)
  }

  async removeProjectMcpServer(projectDir: string, name: string): Promise<void> {
    const mcpFile = this.getProjectMcpFile(projectDir)
    const config = await fsService.readJSON<{ mcpServers?: Record<string, unknown> }>(mcpFile)
    if (config.mcpServers) {
      delete config.mcpServers[name]
      await fsService.writeJSON(mcpFile, config)
    }
  }

  // --- Project Info ---

  async getProjectInfo(projectDir: string): Promise<ProjectDetailInfo> {
    const agentsDir = this.getProjectAgentsDir(projectDir)
    const skillsDir = this.getProjectSkillsDir(projectDir)
    const mcpFile = this.getProjectMcpFile(projectDir)
    const settingsFile = join(projectDir, '.claude', 'settings.json')

    const agentFiles = await fsService.listFiles(agentsDir, '.md')
    const skillDirs = await fsService.listDirs(skillsDir)
    // Count only dirs with SKILL.md
    let skillCount = 0
    for (const d of skillDirs) {
      if (d === 'learned') continue
      if (await fsService.exists(join(skillsDir, d, 'SKILL.md'))) skillCount++
    }

    let mcpCount = 0
    if (await fsService.exists(mcpFile)) {
      try {
        const config = await fsService.readJSON<{ mcpServers?: Record<string, unknown> }>(mcpFile)
        mcpCount = Object.keys(config.mcpServers || {}).length
      } catch { /* 0 */ }
    }

    return {
      projectDir,
      projectName: projectDir.split('/').pop() || projectDir,
      agentCount: 0, // populated by caller from session data
      activeCount: 0,
      lastActivity: '',
      projectAgentCount: agentFiles.length,
      projectSkillCount: skillCount,
      projectMcpServerCount: mcpCount,
      hasProjectSettings: await fsService.exists(settingsFile),
    }
  }
}

export const projectConfigService = new ProjectConfigService()
```

**Key design decisions:**
- The service reuses `parserService.parseAgent()` and `parserService.parseSkill()` with the same frontmatter parsing, then overrides `source` to `'project'`. This avoids duplicating parsing logic.
- The `fsService` (existing `FileSystemService`) handles all filesystem operations consistently.
- Project MCP server format matches `.mcp.json` structure observed in the actual `Slack/.mcp.json` file: `{ "mcpServers": { "name": { "type": "sse", "url": "..." } } }`.

