### Phase 5: Zustand Store for Project Config

**New file:** `/Users/yangsmac/Desktop/claude-skills-and-agents-manager/src/renderer/stores/projectConfigStore.ts`

This store manages the state for the currently viewed project's local configurations. It follows the existing store pattern (see `agentStore.ts`, `skillStore.ts`, `mcpStore.ts`).

```typescript
import { create } from 'zustand'
import type { Agent } from '@shared/types/agent'
import type { Skill } from '@shared/types/skill'
import type { MCPServer } from '@shared/types/mcp'

interface ProjectConfigStore {
  projectDir: string | null

  // Project-local agents
  agents: Agent[]
  agentsLoading: boolean

  // Project-local skills
  skills: Skill[]
  skillsLoading: boolean

  // Project-local MCP servers
  mcpServers: MCPServer[]
  mcpLoading: boolean

  // Actions
  setProjectDir: (dir: string) => void

  fetchAgents: (projectDir: string) => Promise<void>
  createAgent: (projectDir: string, name: string, data: { name: string; description: string; tools: string[]; model: string; body: string }) => Promise<void>
  deleteAgent: (projectDir: string, name: string) => Promise<void>

  fetchSkills: (projectDir: string) => Promise<void>
  createSkill: (projectDir: string, name: string, body: string, metadata: Record<string, unknown>) => Promise<void>
  deleteSkill: (projectDir: string, name: string) => Promise<void>

  fetchMcpServers: (projectDir: string) => Promise<void>
  addMcpServer: (projectDir: string, name: string, config: Partial<MCPServer>) => Promise<void>
  removeMcpServer: (projectDir: string, name: string) => Promise<void>
}

export const useProjectConfigStore = create<ProjectConfigStore>((set, get) => ({
  projectDir: null,
  agents: [],
  agentsLoading: false,
  skills: [],
  skillsLoading: false,
  mcpServers: [],
  mcpLoading: false,

  setProjectDir(dir: string) {
    set({ projectDir: dir })
  },

  async fetchAgents(projectDir: string) {
    set({ agentsLoading: true })
    try {
      const agents = await window.electronAPI.projectConfig.agents.list(projectDir)
      set({ agents })
    } finally {
      set({ agentsLoading: false })
    }
  },

  async createAgent(projectDir, name, data) {
    await window.electronAPI.projectConfig.agents.write(projectDir, name, data)
    await get().fetchAgents(projectDir)
  },

  async deleteAgent(projectDir, name) {
    await window.electronAPI.projectConfig.agents.delete(projectDir, name)
    set(state => ({ agents: state.agents.filter(a => a.name !== name) }))
  },

  async fetchSkills(projectDir) {
    set({ skillsLoading: true })
    try {
      const skills = await window.electronAPI.projectConfig.skills.list(projectDir)
      set({ skills })
    } finally {
      set({ skillsLoading: false })
    }
  },

  async createSkill(projectDir, name, body, metadata) {
    await window.electronAPI.projectConfig.skills.write(projectDir, name, body, metadata)
    await get().fetchSkills(projectDir)
  },

  async deleteSkill(projectDir, name) {
    await window.electronAPI.projectConfig.skills.delete(projectDir, name)
    set(state => ({ skills: state.skills.filter(s => s.name !== name) }))
  },

  async fetchMcpServers(projectDir) {
    set({ mcpLoading: true })
    try {
      const mcpServers = await window.electronAPI.projectConfig.mcp.list(projectDir)
      set({ mcpServers })
    } finally {
      set({ mcpLoading: false })
    }
  },

  async addMcpServer(projectDir, name, config) {
    await window.electronAPI.projectConfig.mcp.add(projectDir, name, config)
    await get().fetchMcpServers(projectDir)
  },

  async removeMcpServer(projectDir, name) {
    await window.electronAPI.projectConfig.mcp.remove(projectDir, name)
    await get().fetchMcpServers(projectDir)
  },
}))
```

